"use client";

import { useEffect, useState } from "react";

const slides = [
  {
    image:
      "https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&auto=format&fit=crop&w=2560&q=80",
    alt: "image 1",
    position: "center",
  },
  {
    image:
      "https://images.unsplash.com/photo-1493246507139-91e8fad9978e?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&auto=format&fit=crop&w=2940&q=80",
    alt: "image 2",
    position: "center",
  },
  {
    image:
      "https://images.unsplash.com/photo-1518623489648-a173ef7824f3?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxwaG5vbnx8fHx8&auto=format&fit=crop&w=2762&q=80",
    alt: "image 3",
    position: "bottom",
  },
];

export default function Hero() {
  const [activeSlide, setActiveSlide] = useState(0);

  // Auto slide
  useEffect(() => {
    const interval = setInterval(() => {
      setActiveSlide((prev) => (prev + 1) % slides.length);
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  // Previous slide
  const prevSlide = () => {
    setActiveSlide(
      (prev) => (prev - 1 + slides.length) % slides.length
    );
  };

  // Next slide
  const nextSlide = () => {
    setActiveSlide((prev) => (prev + 1) % slides.length);
  };

  return (
    <div className="relative h-[600px] w-full overflow-hidden">
      {/* Slides */}
      {slides.map((slide, index) => (
        <div
          key={slide.image}
          className={`absolute inset-0 h-full w-full transition-opacity duration-700 ${
            index === activeSlide
              ? "z-10 opacity-100"
              : "z-0 opacity-0"
          }`}
        >
          {/* Image */}
          <img
            src={slide.image}
            alt={slide.alt}
            className="h-full w-full object-cover"
          />

          {/* Overlay */}
          {index === 0 && (
            <div className="absolute inset-0 grid h-full w-full place-items-center bg-black/75">
              <div className="w-3/4 text-center md:w-2/4">
                <h1 className="mb-4 text-3xl font-bold text-white md:text-4xl lg:text-5xl">
                  Welcome to AJ Medical Tourism 
                </h1>

                <p className="mb-12 text-lg text-white opacity-80">
                  India's Top Specialised Medical Profssionals and Hospitals. 
                </p>

                <div className="flex justify-center gap-2">
                  <button
                    type="button"
                    className="rounded-lg bg-white px-6 py-3 text-base font-medium text-black shadow-md transition hover:bg-gray-200"
                  >
                   Click Here
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Slide 2 */}
          {index === 1 && (
            <div className="absolute inset-0 grid h-full w-full place-items-center bg-black/75">
              <div className="w-3/4 text-center md:w-2/4">
                <h1 className="mb-4 text-3xl font-bold text-white md:text-4xl lg:text-5xl">
                  India's Top Specialised Medical Profssionals
                </h1>

                <p className="mb-12 text-lg text-white opacity-80">
                  Are you looking for the best spine surgeon and spine specialist  hospital  in india? 
                </p>

                <div className="flex justify-center gap-2">
                  <button
                    type="button"
                    className="rounded-lg bg-white px-6 py-3 text-base font-medium text-black shadow-md transition hover:bg-gray-200"
                  >
                    Click Here
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Slide 3 */}
          {index === 2 && (
            <div className="absolute inset-0 grid h-full w-full place-items-center bg-black/75">
              <div className="w-3/4 text-center md:w-2/4">
                <h1 className="mb-4 text-3xl font-bold text-white md:text-4xl lg:text-5xl">
                  World Class Medical Facilities
                </h1>

                <p className="mb-12 text-lg text-white opacity-80">
                  Start your  Journey to Good  Health with AJ Medical Tourism   
                </p>

                <div className="flex justify-center gap-2">
                  <button
                    type="button"
                    className="rounded-lg bg-white px-6 py-3 text-base font-medium text-black shadow-md transition hover:bg-gray-200"
                  >
                    Click Here
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      ))}

      {/* Previous Button */}
      <button
        type="button"
        onClick={prevSlide}
        aria-label="Previous slide"
        className="absolute left-4 top-1/2 z-20 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/20 text-2xl text-white backdrop-blur-sm transition hover:bg-white/40"
      >
        ‹
      </button>

      {/* Next Button */}
      <button
        type="button"
        onClick={nextSlide}
        aria-label="Next slide"
        className="absolute right-4 top-1/2 z-20 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/20 text-2xl text-white backdrop-blur-sm transition hover:bg-white/40"
      >
        ›
      </button>

      {/* Dots */}
      <div className="absolute bottom-5 left-1/2 z-20 flex -translate-x-1/2 gap-2">
        {slides.map((_, index) => (
          <button
            key={index}
            type="button"
            onClick={() => setActiveSlide(index)}
            aria-label={`Go to slide ${index + 1}`}
            className={`h-2.5 rounded-full transition-all ${
              activeSlide === index
                ? "w-8 bg-white"
                : "w-2.5 bg-white/50"
            }`}
          />
        ))}
      </div>
    </div>
  );
}